import json
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'results/model_improvement/next_direction_analysis'
def met(tp,fp,fn):
 p=tp/(tp+fp) if tp+fp else 0;r=tp/(tp+fn) if tp+fn else 0
 return dict(TP=tp,FP=fp,FN=fn,precision=p,recall=r,f1=2*p*r/(p+r) if p+r else 0)
def main():
 r=json.loads((OUT/'evaluation.json').read_text());base=json.loads((ROOT/'results/cnn_v4/qrs_verification_v4a/evaluation.json').read_text());beats=json.loads((OUT/'beat_diagnostics.json').read_text());orrows=[]
 lines=['# V4 recall: next direction analysis','','No Test, training, threshold change or firmware modification. Frozen final V4(.88), V6(.87), V11(.80); ECG windows from unchanged detector. V4 scores reused, paired V6/V11 scores supplemented because old aggregate metrics did not preserve per-peak pairing. Native stage probe observes accepted centers and completed windows without changing detector; emitted centers asserted identical to old traces for every record.','','## Evidence boundaries','','Reuse V4-A locked group split: Fit37 records, Calibration19, Evaluation45; MIT record/INCART patient groups disjoint. No parameter or routing classifier is learned/selected in this analysis. Hypotheses and fixed OR diagnostics recorded before Evaluation. Earlier research exposed these groups, and many Evaluation records were used in the frozen CNNs Fit. Train predictions are in-sample, NOT OOF. These are paired internal diagnostic observations, not independent predictive validation. Original Development-only results can be derived from the retained record rows, but are selection-exposed too.','','## FN decomposition and paired trade-offs on Evaluation','','| Dataset | Reference PVC | No accepted detector center | Accepted but no completed window | CNN V4 Normal | Other/matching unresolved | V11 rescues | V6 rescues | All3 miss matched PVC | New N FP by V11 | New N FP by V6 |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for ds,s in r['summary']['Evaluation'].items():lines.append(f"| {ds} | {s['reference_V']} | {s['v4_FN_detector']} | {s['v4_FN_window']} | {s['v4_FN_CNN']} | {s['v4_FN_other']} | {s['PVC_v4miss_v11rescue']} | {s['PVC_v4miss_v6rescue']} | {s['PVC_all_wrong']} | {s['N_v4correct_v11FP']} | {s['N_v4correct_v6FP']} |")
 lines+=['','“No center” includes warm-up, amplitude/refractory and matching failures; it does not prove there was no physiological R wave. Accepted-without-window is measured from the same native replay, not guessed from missing emitted peaks. OTHER excluded N/V labels; all missing V retained FN. Scope unmatched alarms remain additional FP, not automatically noise. Ungated pipeline, no physical quality-gate/latency simulation.','','## Fixed OR diagnostic — actual predictions, not an oracle','', '| Role | Dataset | Rule | Precision | Recall | F1 | FP | FN |','|---|---|---|---:|---:|---:|---:|---:|']
 for role in ['Fit','Calibration','Evaluation']:
  for ds,s in r['summary'][role].items():
   b=base['summary'][role]['baseline'][ds];assert b['FN']==s['v4_FN_detector']+s['v4_FN_window']+s['v4_FN_CNN']+s['v4_FN_other']
   for rule,key,fpkey in [('V4',None,None),('V4 OR V6','PVC_v4miss_v6rescue','or6_extra_FP'),('V4 OR V11','PVC_v4miss_v11rescue','or11_extra_FP')]:
    m=met(b['TP']+(s[key] if key else 0),b['FP']+(s[fpkey] if fpkey else 0),b['FN']-(s[key] if key else 0));orrows.append(dict(role=role,dataset=ds,rule=rule,**m));lines.append(f"| {role} | {ds} | {rule} | {100*m['precision']:.2f}% | {100*m['recall']:.2f}% | {100*m['f1']:.2f}% | {m['FP']} | {m['FN']} |")
 lines+=['','OR retains all V4 PVC alarms and adds partner alarms at unchanged thresholds. Added unmatched alarms count FP. Rescue counts are ground-truth diagnostic intersections, NOT achievable conditional selection accuracy. No runtime rule knows which V4 misses are true PVC. A selected cascade would require a separately fixed/calibrated router and new evaluation; it was not created here.','','## Morphology/context hypotheses','','Metrics are diagnostic proxies: central128 normalized PTP; half-amplitude support count (not clinical QRS duration); current detected RR; correlation with previous raw detector window; central energy ratio. Neighbor window can overlap the current256 window; high correlation is not independent beat morphology evidence. No annotation-neighbor labels are used as input. Score distributions use each fixed model, not re-calibrated confidence.','', '| Role | Dataset | Group | n | PTP median | Support ms median | RR median | Previous-window corr median | Energy ratio median | V4 score median | V11 score median |','|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for role in ['Fit','Calibration','Evaluation']:
  for ds,groups in r['feature_summary'][role].items():
   for tag,s in groups.items():
    if tag=='other':continue
    vals=[s[k]['median'] for k in ['central_ptp_z','half_support_ms','RR','previous_window_correlation','central_energy_ratio','s4','s11']];lines.append('| '+' | '.join([role,ds,tag,str(s['n'])]+[f'{v:.4f}' for v in vals])+' |')
 lines+=['','IQRs and full individual observations in evaluation.json/beat_diagnostics.json. Overlap between rescued PVC and new-FP Normal morphology/RR distributions means medians alone cannot justify a runtime rule. Width and neighbor similarity are hypotheses; contributions of learned morphology, RR and distribution shift are not causally isolated. PVC all-wrong and Normal all-wrong counts per record/group are preserved.','','## Three options and ESP32 cost estimates','','| Direction | Evidence/potential | Approximate embedded cost | Main unresolved requirement |','|---|---|---|---|','| A V4+temporal/morphology context | Can describe missed PVC and existing QRS-verification limits; no validated decision rule yet | V4 raw FP32 weights3396B plus feature code; one previous float ECG window1024B and8 int64 timestamps64B if needed; O(256) feature scan; model latency plus feature time, board PENDING | Fit-only/calibration rule or feature training; avoid rejecting wide/early/low-QRS PVC; causal history/reset policy |','| B focused training with protected Normal negatives | Single-model potential: missed PVC and partner-induced Normal FP provide concrete Train-only targets; no improvement claim before training | If architecture V4 retained,849 weights=3396B FP32; input1024B; runtime should be similar graph class but actual arena/latency PENDING; no required ECG history | Maintain group diversity and class balance; no Test hard negatives; Evaluate once with separate groups and protect hard-negative N |','| C V4+V11 controlled cascade | Paired rescue exists, but actual OR also adds false alarms; not evidence of a working controlled router | Raw FP32 weights3396+8068=11464B excluding graph/runtime; shared input1024B plus RR history/scaling; sequential worst-case latency T4+T11+router; arena can only be planned/measured, not assumed additive or reusable | Router reliability, reset/missing-RR policy, independent calibration, full safety gate; no oracle routing |','','These are parameter/input payload calculations, not Tensor Arena or compiled Flash measurements. FP32 deployment, INT8 graph metadata, allocator scratch/persistent state and ESP-NN coverage differ. Actual RAM/Flash and inference time require a separately authorized host/build/board measurement. No such deployment measurements were performed here.','','## Train-only candidate counts for a possible future B experiment']
 mit=np.load(ROOT/'data/processed/mitbih_nv_250hz.npz');sp=np.load(ROOT/'data/processed/mitbih_split_indices.npz');inc=np.load(ROOT/'data/processed/incart_v4_250hz.npz');allowed={'MITBIH':set(mit['record_ids'][sp['train_indices']]),'INCART':set(inc['record_ids'][inc['split']=='train'])};cand={}
 for ds in ['MITBIH','INCART']:
  a=[b for b in beats if b['dataset']==ds and b['record'] in allowed[ds] and b['role']=='Fit'];cand[ds]={'matched_PVC_V4miss':sum(b['symbol']=='V' and b['s4']<.88 for b in a),'protected_N_V4correct_V11_FP':sum(b['symbol']=='N' and b['s4']<.88 and b['s11']>=.8 for b in a)};lines.append(ds+': '+json.dumps(cand[ds]))
 lines+=['','Use only these original-Train groups for future hard-example construction; do not mine Evaluation, original Development or Test for training examples. This artifact identifies counts, not a new dataset or model.','','## Record/patient diagnostic detail','', '| Role | Dataset | Record | Group | Detector FN | Window FN | CNN FN | V11 rescue | New N FP V11 | OR11 extra FP incl unmatched |','|---|---|---|---|---:|---:|---:|---:|---:|---:|']
 for s in r['records']:lines.append(f"| {s['role']} | {s['dataset']} | {s['record']} | {s['group']} | {s['v4_FN_detector']} | {s['v4_FN_window']} | {s['v4_FN_CNN']} | {s['PVC_v4miss_v11rescue']} | {s['N_v4correct_v11FP']} | {s['or11_extra_FP']} |")
 write=lambda name,v:(OUT/name).write_text(json.dumps(v,indent=2));write('fixed_OR_diagnostic.json',orrows);write('Train_only_candidate_counts.json',cand);(OUT/'report.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps({'Evaluation':r['summary']['Evaluation'],'OR_Evaluation':[x for x in orrows if x['role']=='Evaluation']},indent=2))
if __name__=='__main__':main()
